-- Find all products that have never generated any sales.
SELECT DISTINCT
    s.`Item code`,
    s.Description,
    s.Category
FROM items_and_stock s
LEFT JOIN sales_by_item_month sm
    ON s.`Item code` = sm.`Item code`
WHERE sm.`Item code` IS NULL;

-- Business question: Find the total revenue generated by each product, including products with zero revenue.
SELECT
    s.`Item code`,
    s.Description,
    s.Category,
    COALESCE(ROUND(SUM(sm.Revenue), 2), 0) AS total_revenue
FROM items_and_stock s
LEFT JOIN sales_by_item_month sm
    ON s.`Item code` = sm.`Item code`
GROUP BY
    s.`Item code`,
    s.Description,
    s.Category
ORDER BY total_revenue ASC;

/* Find all products that have no matching sales record.
Products with no sales.
Customers with no transactions.
Suppliers with no purchase orders.
Employees with no assigned projects.*/

SELECT DISTINCT
    s.`Item code`,
    s.Description,
    s.Category
FROM items_and_stock s
LEFT JOIN sales_by_item_month sm
    ON s.`Item code` = sm.`Item code`
WHERE sm.`Item code` IS NULL;

-- Find the top 10 products by total revenue, including their product descriptions

SELECT
    p.`Item code`,
    p.Description,
    COALESCE(ROUND(s.total_revenue, 2), 0) AS total_revenue
FROM (
    SELECT DISTINCT
        `Item code`,
        Description
    FROM items_and_stock
) p
LEFT JOIN (
    SELECT
        `Item code`,
        SUM(Revenue) AS total_revenue
    FROM sales_by_item_month
    GROUP BY `Item code`
) s
    ON p.`Item code` = s.`Item code`
ORDER BY total_revenue DESC
LIMIT 10;


-- Which products generate the highest revenue?
-- We need to connect product information from items_and_stock with sales performance from sales_by_item_month.


SELECT
    s.`Item code`,
    s.Description,
    s.Category,
    p.Supplier,
    SUM(s.Revenue) AS total_revenue
FROM sales_by_item_month s
LEFT JOIN (
    SELECT DISTINCT
        `Item code`,
        Supplier
    FROM items_and_stock
) p
    ON s.`Item code` = p.`Item code`
GROUP BY
    s.`Item code`,
    s.Description,
    s.Category,
    p.Supplier
ORDER BY total_revenue DESC
;

-- Find products that have available inventory but have never generated sales.
SELECT DISTINCT
    s.`Item code`,
    s.Description,
    s.Category,
    s.`Qty available`
FROM items_and_stock s
LEFT JOIN (
    SELECT DISTINCT
        `Item code`
    FROM sales_by_item_month
) p
    ON s.`Item code` = p.`Item code`
WHERE s.Period = (
    SELECT MAX(Period)
    FROM items_and_stock
)
AND s.`Qty available` > 0
AND p.`Item code` IS NULL
ORDER BY s.`Qty available` DESC;
/*Now find products that:
- Have available inventory greater than zero.
- Have generated sales in the past.
- Have not generated any sales in the latest sales month.*/
SELECT DISTINCT
    s.`Item code`,
    s.Description,
    s.Category,
    s.`Qty available`
FROM items_and_stock s
LEFT JOIN (
    SELECT DISTINCT `Item code`
	FROM sales_by_item_month
	WHERE Month = (
    SELECT MAX(Month)
    FROM sales_by_item_month
)
) p
    ON s.`Item code` = p.`Item code`
    WHERE s.Period = (
    SELECT MAX(Period)
    FROM items_and_stock
)
AND s.`Qty available` > 0
AND p.`Item code` IS NULL
ORDER BY s.`Qty available` DESC;

